// ─── SEED FUNCTION ──────────────────────────────────────────────────────────

async function seed() {
  console.log("🌱 Starting seed...\n");

  // Additive-only: never delete existing roadmaps — skip by title if already present
  const existingRoadmaps = await db.select().from(roadmaps);
  console.log(`  Found ${existingRoadmaps.length} existing roadmaps — skipping duplicates by title.`);

  let roadmapsAdded = 0;
  let stepsAdded = 0;
  for (const rm of ROADMAPS) {
    const alreadyExists = existingRoadmaps.find(r => r.title === rm.title);
    if (alreadyExists) {
      console.log(`  ⏭  Skipping (already exists): ${rm.title}`);
      continue;
    }
    const [created] = await db
      .insert(roadmaps)
      .values({ title: rm.title, description: rm.description, category: rm.category, icon: rm.icon })
      .returning();
    for (const step of rm.steps) {
      await db.insert(roadmapSteps).values({
        roadmapId: created.id,
        title: step.title,
        description: step.description,
        resources: JSON.stringify(step.resources),
        section: step.section,
        order: step.order,
      });
      stepsAdded++;
    }
    roadmapsAdded++;
    console.log(`  ✅ Added roadmap: ${rm.title} (${rm.steps.length} steps)`);
  }

  // Full reset of resources to apply new data/structure
  await db.delete(resources);
  let resourcesAdded = 0;
  for (const res of RESOURCES) {
    await db.insert(resources).values({
      title: res.title,
      description: res.description,
      category: res.category,
      subcategory: res.subcategory,
      url: res.url,
      tags: JSON.stringify(res.tags),
      warning: res.warning ?? null,
      submittedBy: "4ever-rooted",
    });
    resourcesAdded++;
  }
  console.log(`  ✅ Added ${resourcesAdded} resources across categories`);

  console.log(`\n🎉 Seed complete!`);
  console.log(`   Roadmaps: ${roadmapsAdded} (${stepsAdded} total steps)`);
  console.log(`   Resources: ${resourcesAdded}`);
  process.exit(0);
}

seed().catch(err => {
  console.error("Seed failed:", err);
  process.exit(1);
});
